export interface OrderLine {
  slug: string
  name: string
  qty: number
}

/** A stored order. Amounts are the server's charge, formatted like the quote API (`19.99 USD`). */
export interface Order {
  id: string
  subtotal: string
  discount: string
  total: string
  lines: OrderLine[]
}

import type { CartLine } from '#shared/types/cart'
import type { Order } from '#shared/types/order'

/** Orders live in server memory only; they are lost on restart. */
const orders = new Map<string, Order>()

/** Quotes the lines with the server's prices and stores the resulting order. */
export function createOrder(lines: CartLine[], code?: string): Order {
  const quote = computeQuote(lines, code)
  const order: Order = {
    id: crypto.randomUUID(),
    ...quote,
    lines: lines.map(line => ({
      slug: line.slug,
      name: findProduct(line.slug)?.name ?? line.slug,
      qty: line.qty,
    })),
  }
  orders.set(order.id, order)
  return order
}

export function findOrder(id: string): Order | undefined {
  return orders.get(id)
}

import type { CartLine } from '#shared/types/cart'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: CartLine[], code?: string }>(event)
  const { id, subtotal, discount, total } = createOrder(body?.lines ?? [], body?.code)
  return { id, subtotal, discount, total }
})

export default defineEventHandler((event) => {
  const order = findOrder(getRouterParam(event, 'id') ?? '')
  if (!order)
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  return order
})

